                int best = 0;
                for (int j = 1; j < produced; j++) if (sel[j] < sel[best]) best = j;
                eigenvalues[slot] = lam[best];
                for (int i = 0; i < n; i++) eigenvectors[slot, i] = ritz[best, i];
                sel[best] = float.MaxValue;
            }

            return info;
        }

